1	// Package batchreg registers supply-chain batches in a local JSON file.
2	//
3	// The registry file format is public and stable:
4	//
5	//	{
6	//	  "version": 1,
7	//	  "batches": [
8	//	    {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
9	//	  ]
10	//	}
11	//
12	// Batch ids are unique per file (compared byte for byte, so casing and
13	// interior characters matter). Re-registering an existing id with the same
14	// product, quantity and unit is an idempotent duplicate confirmation; any
15	// differing field is rejected without touching stored records.
16	package batchreg
17	
18	import (
19		"bytes"
20		"encoding/json"
21		"errors"
22		"fmt"
23		"io"
24		"io/fs"
25		"os"
26		"path/filepath"
27		"regexp"
28		"strconv"
29		"strings"
30		"unicode/utf8"
31	)
32	
33	// FormatVersion is the only registry file format understood by this build.
34	const FormatVersion = 1
35	
36	// MaxQuantity is the inclusive upper bound for a batch quantity.
37	const MaxQuantity = int64(1<<63 - 1)
38	
39	var quantityPattern = regexp.MustCompile(`^[0-9]+$`)
40	
41	// Batch is the four-piece record of one supply-chain batch.
42	type Batch struct {
43		Batch    string `json:"batch"`
44		Product  string `json:"product"`
45		Quantity int64  `json:"quantity"`
46		Unit     string `json:"unit"`
47	}
48	
49	// Registry is the on-disk registry file.
50	type Registry struct {
51		Version int     `json:"version"`
52		Batches []Batch `json:"batches"`
53	}
54	
55	// Input is a normalized registration request.
56	type Input struct {
57		Batch    string
58		Product  string
59		Quantity int64
60		Unit     string
61	}
62	
63	// Outcome reports what Register did.
64	type Outcome struct {
65		Batch   Batch
66		Created bool // true when a record was added, false for an identical repeat
67	}
68	
69	// ConflictError reports that a batch id is already held by a different record.
70	// Fields lists every differing member among "product", "quantity" and "unit".
71	type ConflictError struct {
72		Batch  string
73		Fields []string
74	}
75	
76	func (e *ConflictError) Error() string {
77		return fmt.Sprintf("batch %q is already registered with conflicting field(s): %s; the existing record cannot be overwritten",
78			e.Batch, strings.Join(e.Fields, ", "))
79	}
80	
81	// DuplicateIDError reports two stored records sharing one batch id.
82	// First and Second are the 1-based positions of the two records in the
83	// batches array when known.
84	type DuplicateIDError struct {
85		Batch  string
86		First  int
87		Second int
88	}
89	
90	func (e *DuplicateIDError) Error() string {
91		if e.First > 0 && e.Second > 0 {
92			return fmt.Sprintf("registry contains multiple records for batch %q (records %d and %d)", e.Batch, e.First, e.Second)
93		}
94		return fmt.Sprintf("registry contains multiple records for batch %q", e.Batch)
95	}
96	
97	// FormatError reports a structural violation of the public registry file
98	// format: a missing, duplicated, misspelled, null or mistyped field, either
99	// in the root object (Position == 0) or in one batch record (Position is its
100	// 1-based index in "batches"). Batch carries the record's batch id only when
101	// it is uniquely determined; it stays empty when the "batch" member itself
102	// is missing, duplicated or not a string.
103	type FormatError struct {
104		Position int
105		Batch    string
106		Field    string
107		Reason   string
108	}
109	
110	func (e *FormatError) Error() string {
111		where := "root object"
112		if e.Position > 0 {
113			where = fmt.Sprintf("batches record %d", e.Position)
114			if e.Batch != "" {
115				where += fmt.Sprintf(" (batch %q)", e.Batch)
116			}
117		}
118		if e.Field != "" {
119			return fmt.Sprintf("%s: field %q: %s", where, e.Field, e.Reason)
120		}
121		return fmt.Sprintf("%s: %s", where, e.Reason)
122	}
123	
124	// EncodingError reports that a text field is not valid UTF-8: either the
125	// bytes of a CLI argument, or a JSON string value whose source bytes hold
126	// malformed UTF-8 or a lone surrogate escape. The offending value is never
127	// quoted back, since decoding it would substitute U+FFFD and make distinct
128	// inputs collide. Field is one of "batch", "product" and "unit". Inside a
129	// manifest, ParseManifest wraps this in a ManifestRecordError carrying the
130	// 1-based record position.
131	type EncodingError struct {
132		Field string
133	}
134	
135	func (e *EncodingError) Error() string {
136		return fmt.Sprintf("field %q contains bytes that are not valid UTF-8; the value is rejected instead of being replaced with U+FFFD", e.Field)
137	}
138	
139	// NormalizeField trims leading and trailing whitespace; the result must stay
140	// non-empty and be valid UTF-8. Interior characters, including interior
141	// whitespace, are kept, and casing is preserved so "B1" and "b1" are
142	// different values. A genuine replacement character (U+FFFD) is ordinary
143	// text; only malformed UTF-8 bytes are refused.
144	func NormalizeField(value string) (string, error) {
145		if !utf8.ValidString(value) {
146			return "", errors.New("value is not valid UTF-8 text")
147		}
148		trimmed := strings.TrimSpace(value)
149		if trimmed == "" {
150			return "", errors.New("value must not be empty after trimming whitespace")
151		}
152		return trimmed, nil
153	}
154	
155	// ParseQuantity accepts a decimal positive integer made only of ASCII digits
156	// 0-9. Leading zeros are allowed; the numeric value is what gets stored and
157	// compared. Zero, signs, fractions, non-ASCII digits and values above the
158	// signed 64-bit maximum are rejected.
159	func ParseQuantity(text string) (int64, error) {
160		if !quantityPattern.MatchString(text) {
161			return 0, fmt.Errorf("quantity %q must be a positive decimal integer made only of digits 0-9", text)
162		}
163		value, err := strconv.ParseInt(text, 10, 64)
164		if err != nil {
165			return 0, fmt.Errorf("quantity %q must be a positive integer no greater than %d", text, MaxQuantity)
166		}
167		if value == 0 {
168			return 0, fmt.Errorf("quantity %q must be greater than zero", text)
169		}
170		return value, nil
171	}
172	
173	var (
174		errStringNotJSON  = errors.New("value is not a JSON string")
175		errStringEncoding = errors.New("JSON string contains bytes that are not valid UTF-8")
176	)
177	
178	// unmarshalStringStrict decodes one JSON string literal into a Go string
179	// without encoding/json's silent U+FFFD substitution. The literal must be
180	// syntactically valid JSON (only the single token, no trailing data) and the
181	// decoded text must be valid Unicode: malformed UTF-8 source bytes and lone
182	// surrogate escapes are refused, while a genuine U+FFFD — written directly
183	// or as the escape "�" — is ordinary text. Syntax problems return
184	// errStringNotJSON; encoding problems return errStringEncoding.
185	func unmarshalStringStrict(raw json.RawMessage) (string, error) {
186		token := trimJSONSpace(raw)
187		if len(token) < 2 || token[0] != '"' || token[len(token)-1] != '"' {
188			return "", errStringNotJSON
189		}
190		var b strings.Builder
191		b.Grow(len(token))
192		i := 1
193		for i < len(token)-1 {
194			c := token[i]
195			switch {
196			case c == '"':
197				// An unescaped quote before the final byte ends the literal
198				// early, so anything following it is trailing data.
199				return "", errStringNotJSON
200			case c == '\\':
201				if i+1 >= len(token)-1 {
202					return "", errStringNotJSON
203				}
204				switch token[i+1] {
205				case '"', '\\', '/':
206					b.WriteByte(token[i+1])
207					i += 2
208				case 'b':
209					b.WriteByte('\b')
210					i += 2
211				case 'f':
212					b.WriteByte('\f')
213					i += 2
214				case 'n':
215					b.WriteByte('\n')
216					i += 2
217				case 'r':
218					b.WriteByte('\r')
219					i += 2
220				case 't':
221					b.WriteByte('\t')
222					i += 2
223				case 'u':
224					r, size, err := decodeUnicodeEscape(token[i:])
225					if err != nil {
226						return "", err
227					}
228					if _, err := b.WriteRune(r); err != nil {
229						return "", errStringEncoding
230					}
231					i += size
232				default:
233					return "", errStringNotJSON
234				}
235			case c < 0x20:
236				// Raw control characters must be escaped in JSON.
237				return "", errStringNotJSON
238			default:
239				r, size := utf8.DecodeRune(token[i : len(token)-1])
240				if r == utf8.RuneError && size == 1 {
241					return "", errStringEncoding
242				}
243				b.WriteRune(r)
244				i += size
245			}
246		}
247		if i != len(token)-1 {
248			return "", errStringNotJSON
249		}
250		return b.String(), nil
251	}
252	
253	// decodeUnicodeEscape reads a "\uXXXX" escape (or a UTF-16 surrogate pair
254	// "\uHHHH\uLLLL") at the start of p, returning the rune and the number of
255	// bytes consumed. A high surrogate not followed by a low surrogate, a low
256	// surrogate with no high one, or a non-hex code unit are encoding errors.
257	func decodeUnicodeEscape(p []byte) (rune, int, error) {
258		hi, ok := hex4(p)
259		if !ok {
260			return 0, 0, errStringNotJSON
261		}
262		switch {
263		case hi >= 0xD800 && hi <= 0xDBFF:
264			if len(p) < 12 || p[6] != '\\' || p[7] != 'u' {
265				return 0, 0, errStringEncoding
266			}
267			lo, ok := hex4(p[6:])
268			if !ok {
269				return 0, 0, errStringNotJSON
270			}
271			if lo < 0xDC00 || lo > 0xDFFF {
272				return 0, 0, errStringEncoding
273			}
274			return 0x10000 + (rune(hi)-0xD800)<<10 + (rune(lo) - 0xDC00), 12, nil
275		case hi >= 0xDC00 && hi <= 0xDFFF:
276			return 0, 0, errStringEncoding
277		default:
278			return rune(hi), 6, nil
279		}
280	}
281	
282	// hex4 reads the four hex digits following a leading "\u" (p[:2] == `\u`).
283	func hex4(p []byte) (int, bool) {
284		if len(p) < 6 || p[0] != '\\' || p[1] != 'u' {
285			return 0, false
286		}
287		v := 0
288		for _, c := range p[2:6] {
289			var d byte
290			switch {
291			case c >= '0' && c <= '9':
292				d = c - '0'
293			case c >= 'a' && c <= 'f':
294				d = c - 'a' + 10
295			case c >= 'A' && c <= 'F':
296				d = c - 'A' + 10
297			default:
298				return 0, false
299			}
300			v = v<<4 | int(d)
301		}
302		return v, true
303	}
304	
305	// Load reads the registry at path. A missing file yields an empty registry
306	// with existed == false. An existing file that is empty, not parseable as
307	// the public format — including missing, null, duplicated, misspelled or
308	// mistyped fields — of an unsupported version, or holding duplicate batch
309	// ids is an error: callers must never overwrite such a file as if it were a
310	// fresh registry.
311	func Load(path string) (reg *Registry, existed bool, err error) {
312		data, err := os.ReadFile(path)
313		if err != nil {
314			if errors.Is(err, fs.ErrNotExist) {
315				return &Registry{Version: FormatVersion}, false, nil
316			}
317			return nil, false, fmt.Errorf("cannot read registry %q: %w", path, err)
318		}
319		if len(bytes.TrimSpace(data)) == 0 {
320			return nil, true, fmt.Errorf("registry file %q is empty; refusing to replace it with a new registry", path)
321		}
322		reg, err = decode(data)
323		if err != nil {
324			return nil, true, fmt.Errorf("cannot parse registry %q as version %d JSON: %w", path, FormatVersion, err)
325		}
326		if err := validate(reg); err != nil {
327			return nil, true, fmt.Errorf("registry %q is not usable: %w", path, err)
328		}
329		return reg, true, nil
330	}
331	
332	// decode parses data as the public registry format. The root must be a JSON
333	// object holding exactly "version" (the integer 1) and "batches" (an array,
334	// possibly empty); every record must be an object holding exactly "batch",
335	// "product", "quantity" and "unit". Field names are matched case-sensitively
336	// after JSON string decoding, so "Version" or "Batch" are unknown fields and
337	// an escaped respelling such as "bat\u0063h" counts as the same field. A
338	// field appearing twice in one object is rejected even when both values are
339	// identical; missing fields, nulls, wrong types and unknown fields are
340	// rejected just the same. Nothing is patched up by taking the later value,
341	// merging or defaulting.
342	func decode(data []byte) (*Registry, error) {
343		dec := json.NewDecoder(bytes.NewReader(data))
344		var root json.RawMessage
345		if err := dec.Decode(&root); err != nil {
346			return nil, err
347		}
348		var extra json.RawMessage
349		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
350			if err == nil {
351				return nil, errors.New("unexpected data after registry object")
352			}
353			return nil, err
354		}
355	
356		fields, err := parseObjectFields(root)
357		if err != nil {
358			return nil, &FormatError{Reason: "root must be a JSON object holding exactly \"version\" and \"batches\""}
359		}
360		if dup, ok := duplicateField(fields); ok {
361			return nil, &FormatError{Field: dup, Reason: "field appears more than once; duplicate fields are not allowed"}
362		}
363		for _, f := range fields {
364			if f.key != "version" && f.key != "batches" {
365				return nil, &FormatError{Field: f.key, Reason: "unknown field; only \"version\" and \"batches\" are allowed"}
366			}
367		}
368		versionRaw, ok := findField(fields, "version")
369		if !ok {
370			return nil, &FormatError{Field: "version", Reason: "required field is missing"}
371		}
372		batchesRaw, ok := findField(fields, "batches")
373		if !ok {
374			return nil, &FormatError{Field: "batches", Reason: "required field is missing"}
375		}
376		version, err := parseRegistryVersion(versionRaw)
377		if err != nil {
378			return nil, err
379		}
380		if trimmed := bytes.TrimSpace(batchesRaw); len(trimmed) == 0 || trimmed[0] != '[' {
381			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
382		}
383		var elems []json.RawMessage
384		if err := json.Unmarshal(batchesRaw, &elems); err != nil {
385			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
386		}
387		reg := &Registry{Version: version, Batches: make([]Batch, 0, len(elems))}
388		for i, raw := range elems {
389			b, err := parseRegistryRecord(raw, i+1)
390			if err != nil {
391				return nil, err
392			}
393			reg.Batches = append(reg.Batches, b)
394		}
395		return reg, nil
396	}
397	
398	// parseRegistryVersion accepts exactly the integer literal of FormatVersion.
399	// Other integers report an unsupported version; anything else (strings,
400	// fractions, exponents, booleans, null, arrays, objects) is a type error.
401	func parseRegistryVersion(raw json.RawMessage) (int, error) {
402		token := string(bytes.TrimSpace(raw))
403		if isJSONInteger(token) {
404			if token == strconv.Itoa(FormatVersion) {
405				return FormatVersion, nil
406			}
407			return 0, fmt.Errorf("unsupported registry version: got %s, want %d", token, FormatVersion)
408		}
409		return 0, &FormatError{Field: "version", Reason: fmt.Sprintf("must be the integer %d, not %s", FormatVersion, token)}
410	}
411	
412	// parseRegistryRecord validates one batches element: a JSON object with
413	// exactly the four required lowercase fields, text fields as JSON strings
414	// and quantity as a strict JSON integer in 1..MaxQuantity. pos is the
415	// record's 1-based position in the batches array.
416	//
417	// The structural rules (member names, strict string decoding, quantity
418	// range) are shared with parseManifestRecord; only this source's reporting
419	// differs: problems are surfaced as *FormatError with registry wording, a
420	// duplicated member anywhere in the object outranks an unknown one, and
421	// text values are read verbatim — validate handles the empty-string case.
422	func parseRegistryRecord(raw json.RawMessage, pos int) (Batch, error) {
423		var b Batch
424		fields, err := parseObjectFields(raw)
425		if err != nil {
426			return b, &FormatError{Position: pos, Reason: "record must be a JSON object holding exactly \"batch\", \"product\", \"quantity\" and \"unit\""}
427		}
428		// The batch id is attached to errors only when it is unambiguous:
429		// exactly one "batch" member carrying a JSON string whose decoded text
430		// is valid UTF-8. When the "batch" member itself is duplicated, or its
431		// bytes are not valid UTF-8, no id (and never a U+FFFD replacement) is
432		// picked arbitrarily.
433		batchID := unambiguousBatchID(fields, textVerbatim)
434		fail := func(field, reason string) (Batch, error) {
435			return Batch{}, &FormatError{Position: pos, Batch: batchID, Field: field, Reason: reason}
436		}
437	
438		switch fault := checkRecordMembers(fields, true); fault.kind {
439		case faultDuplicate:
440			return fail(fault.field, "field appears more than once; duplicate fields are not allowed")
441		case faultUnknown:
442			return fail(fault.field, "unknown field; only \"batch\", \"product\", \"quantity\" and \"unit\" are allowed")
443		}
444	
445		text := func(name string) (string, error) {
446			rawValue, ok := findField(fields, name)
447			value, problem, _ := decodeRecordText(rawValue, ok, textVerbatim)
448			switch problem {
449			case fieldMissing:
450				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "required field is missing"}
451			case fieldEncoding:
452				return "", &FormatError{Position: pos, Batch: batchID, Field: name,
453					Reason: "must be valid UTF-8 text: malformed bytes or lone surrogate escapes are rejected instead of being replaced with U+FFFD"}
454			case fieldNotString:
455				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "must be a JSON string"}
456			}
457			return value, nil
458		}
459		if b.Batch, err = text("batch"); err != nil {
460			return Batch{}, err
461		}
462		if b.Product, err = text("product"); err != nil {
463			return Batch{}, err
464		}
465		if b.Unit, err = text("unit"); err != nil {
466			return Batch{}, err
467		}
468		quantityRaw, ok := findField(fields, "quantity")
469		if !ok {
470			return fail("quantity", "required field is missing")
471		}
472		b.Quantity, err = registryQuantityError(bytes.TrimSpace(quantityRaw))
473		if err != nil {
474			return fail("quantity", err.Error())
475		}
476		return b, nil
477	}
478	
479	// isJSONInteger reports whether token is a JSON number literal without
480	// fraction or exponent. The token comes from validated JSON, so leading
481	// zeros cannot hide extra digits.
482	func isJSONInteger(token string) bool {
483		if token == "" {
484			return false
485		}
486		if token[0] == '-' {
487			token = token[1:]
488		}
489		if token == "" {
490			return false
491		}
492		for i := 0; i < len(token); i++ {
493			if token[i] < '0' || token[i] > '9' {
494				return false
495			}
496		}
497		return true
498	}
499	
500	// objectField is one member of a JSON object in source order; the key is
501	// the decoded JSON string, so escaped spellings compare by meaning.
502	type objectField struct {
503		key   string
504		value json.RawMessage
505	}
506	
507	// parseObjectFields decodes a single JSON object value into its members in
508	// source order, keeping duplicates visible for the caller to reject. Keys
509	// are re-scanned strictly: encoding/json would otherwise hand back U+FFFD
510	// substitutions for malformed key bytes.
511	func parseObjectFields(raw []byte) ([]objectField, error) {
512		trimmed := bytes.TrimSpace(raw)
513		if len(trimmed) == 0 || trimmed[0] != '{' {
514			return nil, errors.New("value is not a JSON object")
515		}
516		dec := json.NewDecoder(bytes.NewReader(trimmed))
517		if _, err := dec.Token(); err != nil { // opening brace
518			return nil, err
519		}
520		var fields []objectField
521		for dec.More() {
522			keyStart := dec.InputOffset()
523			tok, err := dec.Token()
524			keyEnd := dec.InputOffset()
525			if err != nil {
526				return nil, err
527			}
528			key, ok := tok.(string)
529			if !ok {
530				return nil, errors.New("object keys must be JSON strings")
531			}
532			if _, err := unmarshalStringStrict(keyTokenBytes(trimmed, int(keyStart), int(keyEnd))); err != nil {
533				if errors.Is(err, errStringEncoding) {
534					return nil, errors.New("object key contains bytes that are not valid UTF-8")
535				}
536				return nil, err
537			}
538			var value json.RawMessage
539			if err := dec.Decode(&value); err != nil {
540				return nil, err
541			}
542			fields = append(fields, objectField{key: key, value: value})
543		}
544		if _, err := dec.Token(); err != nil { // closing brace
545			return nil, err
546		}
547		return fields, nil
548	}
549	
550	// trimJSONSpace strips only the four JSON whitespace bytes (space, tab,
551	// carriage return, newline). bytes.TrimSpace would also remove U+000B and
552	// other Unicode whitespace, which is illegal around a JSON token and must
553	// therefore be rejected rather than ignored.
554	func trimJSONSpace(b []byte) []byte {
555		isSpace := func(c byte) bool { return c == ' ' || c == '\t' || c == '\r' || c == '\n' }
556		for len(b) > 0 && isSpace(b[0]) {
557			b = b[1:]
558		}
559		for len(b) > 0 && isSpace(b[len(b)-1]) {
560			b = b[:len(b)-1]
561		}
562		return b
563	}
564	
565	// keyTokenBytes isolates one key token inside trimmed[start:end]. The
566	// decoder reports the offset just after the preceding token (so the span
567	// may still contain a separating comma and whitespace), hence the left trim.
568	func keyTokenBytes(trimmed []byte, start, end int) []byte {
569		return bytes.TrimLeft(trimmed[start:end], " \t\r\n,")
570	}
571	
572	// duplicateField returns the first field name appearing more than once.
573	func duplicateField(fields []objectField) (string, bool) {
574		seen := make(map[string]struct{}, len(fields))
575		for _, f := range fields {
576			if _, dup := seen[f.key]; dup {
577				return f.key, true
578			}
579			seen[f.key] = struct{}{}
580		}
581		return "", false
582	}
583	
584	// findField returns the raw value of the first member named name.
585	func findField(fields []objectField, name string) (json.RawMessage, bool) {
586		for _, f := range fields {
587			if f.key == name {
588				return f.value, true
589			}
590		}
591		return nil, false
592	}
593	
594	// countField counts the members named name.
595	func countField(fields []objectField, name string) int {
596		n := 0
597		for _, f := range fields {
598			if f.key == name {
599				n++
600			}
601		}
602		return n
603	}
604	
605	func validate(reg *Registry) error {
606		seen := make(map[string]int, len(reg.Batches))
607		for i, b := range reg.Batches {
608			pos := i + 1
609			if b.Batch == "" || b.Product == "" || b.Unit == "" {
610				return fmt.Errorf("batches record %d (batch %q): batch, product and unit must all be non-empty", pos, b.Batch)
611			}
612			if b.Quantity <= 0 {
613				return fmt.Errorf("batches record %d (batch %q): quantity must be a positive integer", pos, b.Batch)
614			}
615			if first, dup := seen[b.Batch]; dup {
616				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
617			}
618			seen[b.Batch] = pos
619		}
620		return nil
621	}
622	
623	// ManifestRecordError reports a manifest record that is structurally invalid
624	// or carries a quantity outside the accepted range. Position is the record's
625	// 1-based position in the manifest.
626	type ManifestRecordError struct {
627		Position int
628		Batch    string // normalized batch id when available, otherwise ""
629		Reason   string
630	}
631	
632	func (e *ManifestRecordError) Error() string {
633		if e.Batch != "" {
634			return fmt.Sprintf("manifest record %d (batch %q): %s", e.Position, e.Batch, e.Reason)
635		}
636		return fmt.Sprintf("manifest record %d: %s", e.Position, e.Reason)
637	}
638	
639	// ManifestConflictError reports that a manifest record disagrees with the
640	// record already registered, or introduced earlier in the same manifest,
641	// under the same batch id. Position is the record's 1-based position in the
642	// manifest and Fields lists every differing member among "product",
643	// "quantity" and "unit" in that order.
644	type ManifestConflictError struct {
645		Position int
646		Batch    string
647		Fields   []string
648		Source   string // "registry" or "manifest"
649		PrevPos  int    // 1-based position of the earlier manifest record, if Source == "manifest"
650	}
651	
652	func (e *ManifestConflictError) Error() string {
653		if e.Source == "manifest" {
654			return fmt.Sprintf("manifest record %d (batch %q) conflicts with manifest record %d on field(s): %s; the whole manifest is rejected",
655				e.Position, e.Batch, e.PrevPos, strings.Join(e.Fields, ", "))
656		}
657		return fmt.Sprintf("manifest record %d (batch %q) conflicts with the registered record on field(s): %s; the whole manifest is rejected",
658			e.Position, e.Batch, strings.Join(e.Fields, ", "))
659	}
660	
661	// ParseManifest decodes data as a non-empty JSON array holding exactly the
662	// four required fields batch, product, quantity and unit per element. The
663	// three text fields must be JSON strings that are not blank after trimming;
664	// quantity must be a JSON integer (no strings, fractions or exponents) in
665	// the range 1..MaxQuantity. An empty file, empty array, non-array document
666	// or any malformed record is rejected. The manifest bytes are never written.
667	func ParseManifest(data []byte) ([]Input, error) {
668		trimmed := bytes.TrimSpace(data)
669		if len(trimmed) == 0 {
670			return nil, errors.New("manifest file is empty")
671		}
672		if trimmed[0] != '[' {
673			return nil, errors.New("manifest must be a non-empty JSON array of records")
674		}
675	
676		var elems []json.RawMessage
677		dec := json.NewDecoder(bytes.NewReader(data))
678		if err := dec.Decode(&elems); err != nil {
679			return nil, fmt.Errorf("manifest is not valid JSON: %w", err)
680		}
681		var extra json.RawMessage
682		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
683			if err == nil {
684				return nil, errors.New("manifest has unexpected data after the array")
685			}
686			return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
687		}
688		if len(elems) == 0 {
689			return nil, errors.New("manifest must contain at least one record")
690		}
691	
692		inputs := make([]Input, 0, len(elems))
693		for i, raw := range elems {
694			pos := i + 1
695			in, err := parseManifestRecord(raw)
696			if err != nil {
697				return nil, &ManifestRecordError{Position: pos, Batch: in.Batch, Reason: err.Error()}
698			}
699			inputs = append(inputs, in)
700		}
701		return inputs, nil
702	}
703	
704	// batchRecordFields are the only members a batch record may carry, in the
705	// registry file and in an import manifest alike.
706	var batchRecordFields = map[string]struct{}{
707		"batch": {}, "product": {}, "quantity": {}, "unit": {},
708	}
709	
710	// parseManifestRecord validates one manifest element: it must be a JSON
711	// object with exactly the four required keys, text fields as non-blank,
712	// valid UTF-8 strings and quantity as a strict JSON integer. The members
713	// are scanned with parseObjectFields (strict key decoding, duplicates kept
714	// visible) rather than a lenient map unmarshal, so malformed key or value
715	// bytes cannot be silently replaced with U+FFFD. Whatever makes the record
716	// fail — an unknown, duplicated or case-mismatched field included — the
717	// returned Input carries the normalized batch id whenever exactly one
718	// "batch" member holds valid, non-blank text, so the caller can name the
719	// batch in the error; otherwise it stays empty.
720	//
721	// The structural rules are shared with parseRegistryRecord; this source's
722	// own choices are: member-name anomalies are reported in source order
723	// (unknown and duplicate carry equal weight), text is trimmed and must stay
724	// non-empty, and reasons use manifest wording (including *EncodingError for
725	// malformed text).
726	func parseManifestRecord(raw json.RawMessage) (Input, error) {
727		var in Input
728		members, err := parseObjectFields(raw)
729		if err != nil {
730			return in, errors.New("record must be a JSON object with batch, product, quantity and unit")
731		}
732		// Attach the batch id to whatever error this record raises, but only when
733		// it is unambiguous: exactly one "batch" member (compared after JSON key
734		// decoding, so an escaped respelling counts as the same field) carrying a
735		// JSON string whose decoded text is valid UTF-8 and non-blank once
736		// trimmed. A missing, duplicated, mistyped, blank or malformed "batch"
737		// member leaves the id out — never a U+FFFD substitution, and never one
738		// of two duplicate values picked arbitrarily, even when both are equal.
739		// Where the "batch" member sits relative to the offending field does not
740		// matter.
741		in.Batch = unambiguousBatchID(members, textTrimmed)
742	
743		// Manifest member-name problems are reported in source order: the first
744		// unknown name or first repeat fails the record.
745		switch fault := checkRecordMembers(members, false); fault.kind {
746		case faultUnknown:
747			return in, fmt.Errorf("record has unknown field %q; only batch, product, quantity and unit are allowed", fault.field)
748		case faultDuplicate:
749			return in, fmt.Errorf("record lists field %q more than once", fault.field)
750		}
751	
752		textField := func(name string) (string, error) {
753			rawValue, found := findField(members, name)
754			value, problem, cause := decodeRecordText(rawValue, found, textTrimmed)
755			switch problem {
756			case fieldMissing:
757				return "", fmt.Errorf("missing required field %q", name)
758			case fieldNotString:
759				return "", fmt.Errorf("field %q must be a JSON string", name)
760			case fieldEncoding:
761				return "", &EncodingError{Field: name}
762			case fieldBlank:
763				return "", fmt.Errorf("field %q must not be blank: %w", name, cause)
764			}
765			return value, nil
766		}
767	
768		in.Batch, err = textField("batch")
769		if err != nil {
770			return in, err
771		}
772		in.Product, err = textField("product")
773		if err != nil {
774			return in, err
775		}
776		in.Unit, err = textField("unit")
777		if err != nil {
778			return in, err
779		}
780		quantityRaw, ok := findField(members, "quantity")
781		if !ok {
782			return in, errors.New("missing required field \"quantity\"")
783		}
784		in.Quantity, err = manifestQuantityError(bytes.TrimSpace(quantityRaw))
785		if err != nil {
786			return in, err
787		}
788		return in, nil
789	}
790	
791	// ImportResult is one entry of an Import outcome: the normalized record in
792	// manifest order plus whether it was newly created or already present.
793	type ImportResult struct {
794		Batch   Batch
795		Created bool
796	}
797	
798	// validateManifestInput applies the same effective-value rules to one
799	// directly submitted record that Register enforces for single entries and
800	// parseManifestRecord enforces for file records: the three text fields must
801	// be valid UTF-8 and must not be empty strings, and quantity must lie in
802	// 1..MaxQuantity. Text is checked verbatim — direct submissions get no
803	// whitespace trimming or case folding (the command-line entry normalizes
804	// before constructing the Input), so whitespace-only text is accepted as
805	// ordinary non-empty text. pos is the record's 1-based position in this
806	// submission. The returned *ManifestRecordError names the offending field
807	// in its reason and cites the batch id only when that id is itself
808	// non-empty, valid UTF-8 text; it is never invented or substituted when the
809	// batch field is empty or malformed.
810	func validateManifestInput(in Input, pos int) error {
811		// batchID is "" whenever the batch field itself is empty or malformed, so
812		// it is safe to attach it to whichever error follows.
813		batchID := safeBatchIDForError(in.Batch)
814		// Import reports an encoding problem anywhere in the three text fields
815		// before any empty-text problem; quantity problems come after both.
816		issues := inspectRecordText(in.Batch, in.Product, in.Unit)
817		if issue, bad := firstTextIssue(issues, textEncoding); bad {
818			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: (&EncodingError{Field: issue.field}).Error()}
819		}
820		if issue, bad := firstTextIssue(issues, textEmpty); bad {
821			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: fmt.Sprintf("field %q must not be empty", issue.field)}
822		}
823		switch classifyDecodedQuantity(in.Quantity) {
824		case decodedQtyNotPositive:
825			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: `field "quantity" must be greater than zero`}
826		case decodedQtyAboveMax:
827			return &ManifestRecordError{Position: pos, Batch: batchID,
828				Reason: fmt.Sprintf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)}
829		}
830		return nil
831	}
832	
833	// Import validates every record of inputs before appending anything: the
834	// whole manifest fails if any record carries invalid UTF-8, an empty text
835	// field or a quantity outside 1..MaxQuantity — whether its batch id is new,
836	// already stored or seen earlier in this submission — or if any record
837	// conflicts with a stored record or with an earlier manifest record, and reg
838	// is left untouched on error. Directly submitted text is kept verbatim. New
839	// batch ids are appended in first-occurrence order; an id already stored or
840	// introduced earlier in the same manifest is confirmed as a duplicate only
841	// when product, quantity and unit all match. Results come back in manifest
842	// order; Created is false for duplicates.
843	func Import(reg *Registry, inputs []Input) (results []ImportResult, err error) {
844		if reg.Version != FormatVersion {
845			return nil, fmt.Errorf("unsupported registry version %d", reg.Version)
846		}
847		if len(inputs) == 0 {
848			return nil, errors.New("manifest must contain at least one record")
849		}
850		// Reject malformed text and non-effective values before touching
851		// anything; this covers records handed in directly by Go callers the
852		// same way ParseManifest covers file records, so a blank text field or a
853		// non-positive quantity can never reach the new/duplicate/conflict logic
854		// below and end up in a file the reader would refuse. Text is checked
855		// verbatim: direct submissions get no trimming or case folding (only the
856		// command-line entry normalizes, before building the Input).
857		for i, in := range inputs {
858			if err := validateManifestInput(in, i+1); err != nil {
859				return nil, err
860			}
861		}
862	
863		// Work on a copy: a rejected manifest must never partially land in reg.
864		working := append([]Batch(nil), reg.Batches...)
865		indexByID := make(map[string]int, len(working))
866		for i, b := range working {
867			indexByID[b.Batch] = i
868		}
869		firstPos := make(map[string]int, len(inputs)) // manifest 1-based position of a newly introduced id
870	
871		out := make([]ImportResult, len(inputs))
872		for i, in := range inputs {
873			pos := i + 1
874			if idx, known := indexByID[in.Batch]; known {
875				existing := working[idx]
876				diffs := diffFields(existing, in)
877				if len(diffs) > 0 {
878					if prev, inManifest := firstPos[in.Batch]; inManifest {
879						return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "manifest", PrevPos: prev}
880					}
881					return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "registry"}
882				}
883				out[i] = ImportResult{Batch: existing, Created: false}
884				continue
885			}
886			b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
887			working = append(working, b)
888			indexByID[in.Batch] = len(working) - 1
889			firstPos[in.Batch] = pos
890			out[i] = ImportResult{Batch: b, Created: true}
891		}
892	
893		reg.Batches = working
894		return out, nil
895	}
896	
897	// diffFields lists the members of product, quantity and unit in which in
898	// differs from existing, in that fixed order.
899	func diffFields(existing Batch, in Input) []string {
900		var diffs []string
901		if existing.Product != in.Product {
902			diffs = append(diffs, "product")
903		}
904		if existing.Quantity != in.Quantity {
905			diffs = append(diffs, "quantity")
906		}
907		if existing.Unit != in.Unit {
908			diffs = append(diffs, "unit")
909		}
910		return diffs
911	}
912	
913	// Register adds in to reg, or confirms the identical record already stored
914	// under the same batch id. A batch id held by a record differing in product,
915	// quantity or unit produces a *ConflictError and leaves reg untouched. The
916	// zero Outcome is returned together with the error.
917	func Register(reg *Registry, in Input) (Outcome, error) {
918		if reg.Version != FormatVersion {
919			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
920		}
921		// Register reports any empty text field before any encoding problem;
922		// quantity problems come after both.
923		issues := inspectRecordText(in.Batch, in.Product, in.Unit)
924		if _, bad := firstTextIssue(issues, textEmpty); bad {
925			return Outcome{}, errors.New("batch, product and unit must be non-empty")
926		}
927		if issue, bad := firstTextIssue(issues, textEncoding); bad {
928			return Outcome{}, &EncodingError{Field: issue.field}
929		}
930		if !quantityInRange(in.Quantity) {
931			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
932		}
933		for _, b := range reg.Batches {
934			if b.Batch != in.Batch {
935				continue
936			}
937			if diffs := diffFields(b, in); len(diffs) > 0 {
938				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
939			}
940			return Outcome{Batch: b, Created: false}, nil
941		}
942		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
943		reg.Batches = append(reg.Batches, b)
944		return Outcome{Batch: b, Created: true}, nil
945	}
946	
947	// validateForSave checks every record of reg against the rules Load enforces,
948	// so a hand-assembled registry cannot be persisted in a shape the reader
949	// would refuse. Records are checked in order and the first violation is
950	// reported as a *FormatError naming the 1-based record position, the field
951	// and the reason; the batch id is attached only when it is itself non-empty,
952	// valid UTF-8 text — never a U+FFFD substitution for a malformed id. A batch
953	// id seen twice is reported as a *DuplicateIDError carrying both 1-based
954	// positions, even when the two records are identical: Save persists records,
955	// it never confirms duplicates or merges them. Text is checked verbatim —
956	// no trimming, no case folding — and reg is never modified.
957	func validateForSave(reg *Registry) error {
958		seen := make(map[string]int, len(reg.Batches))
959		for i, b := range reg.Batches {
960			pos := i + 1
961			batchID := safeBatchIDForError(b.Batch)
962			// Save reports the first problem in batch, product, unit field
963			// order, with a field's encoding problem ahead of its empty-string
964			// problem — exactly the order inspectRecordText lists issues in.
965			if issues := inspectRecordText(b.Batch, b.Product, b.Unit); len(issues) > 0 {
966				issue := issues[0]
967				if issue.kind == textEncoding {
968					return &FormatError{Position: pos, Batch: batchID, Field: issue.field,
969						Reason: "must be valid UTF-8 text: malformed bytes are rejected instead of being replaced with U+FFFD"}
970				}
971				return &FormatError{Position: pos, Batch: batchID, Field: issue.field, Reason: "must not be empty"}
972			}
973			if !quantityInRange(b.Quantity) {
974				return &FormatError{Position: pos, Batch: batchID, Field: "quantity",
975					Reason: fmt.Sprintf("must be between 1 and %d", MaxQuantity)}
976			}
977			if first, dup := seen[b.Batch]; dup {
978				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
979			}
980			seen[b.Batch] = pos
981		}
982		return nil
983	}
984	
985	// writeTempContent and renameTempFile are the two failure-prone steps of the
986	// atomic save — writing the new content into the temporary file, and replacing
987	// the target with it — kept behind package-level variables so the regression
988	// tests can make a chosen step of a real save fail deterministically, on the
989	// save's actual target rather than a neighboring unusable path. Production
990	// behavior is exactly the wrapped os operations.
991	var (
992		writeTempContent = func(f *os.File, data []byte) (int, error) { return f.Write(data) }
993		renameTempFile   = os.Rename
994	)
995	
996	// Save atomically writes reg to path, replacing the file only after the new
997	// content is fully on disk so an existing registry stays usable on failure.
998	// Records are serialized in their current order; the file is created with
999	// 0644 permissions or, when replacing an existing file, with its permissions.
1000	//
1001	// Every record must satisfy the same effective-value rules Load enforces, so
1002	// a registry saved successfully always reads back: batch, product and unit
1003	// must be non-empty valid UTF-8 text (kept verbatim — no trimming or case
1004	// folding, so whitespace-only text is ordinary non-empty text), quantity
1005	// must lie in 1..MaxQuantity, and batch ids must be unique under exact
1006	// byte-for-byte comparison, two identical records included. Any violation
1007	// rejects the whole save before anything is written: an existing target
1008	// keeps its bytes and modification time, a missing target stays missing and
1009	// no temporary file is left behind. A nil or empty Batches is a legal empty
1010	// registry and is written as "batches": [] without touching reg itself.
1011	func Save(path string, reg *Registry) error {
1012		if reg.Version != FormatVersion {
1013			return fmt.Errorf("cannot write registry format version %d", reg.Version)
1014		}
1015		if err := validateForSave(reg); err != nil {
1016			return fmt.Errorf("cannot save registry %q: %w", path, err)
1017		}
1018		mode := os.FileMode(0o644)
1019		if info, err := os.Stat(path); err == nil {
1020			mode = info.Mode().Perm()
1021		} else if !errors.Is(err, fs.ErrNotExist) {
1022			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
1023		}
1024	
1025		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
1026			return fmt.Errorf("cannot save registry %q: %w", path, err)
1027		}
1028	
1029		// Encode a shallow copy so a nil Batches marshals as [] (null would not
1030		// read back) without mutating the caller's registry.
1031		out := *reg
1032		if out.Batches == nil {
1033			out.Batches = []Batch{}
1034		}
1035		var buf bytes.Buffer
1036		enc := json.NewEncoder(&buf)
1037		enc.SetEscapeHTML(false)
1038		enc.SetIndent("", "  ")
1039		if err := enc.Encode(&out); err != nil {
1040			return fmt.Errorf("cannot encode registry %q: %w", path, err)
1041		}
1042	
1043		tmp, err := os.CreateTemp(filepath.Dir(path), ".govflow-registry-*.tmp")
1044		if err != nil {
1045			return fmt.Errorf("cannot save registry %q: %w", path, err)
1046		}
1047		tmpName := tmp.Name()
1048		abort := func(cause error) error {
1049			tmp.Close()
1050			os.Remove(tmpName)
1051			return fmt.Errorf("cannot save registry %q: %w", path, cause)
1052		}
1053		if _, err := writeTempContent(tmp, buf.Bytes()); err != nil {
1054			return abort(err)
1055		}
1056		if err := tmp.Chmod(mode); err != nil {
1057			return abort(err)
1058		}
1059		if err := tmp.Sync(); err != nil {
1060			return abort(err)
1061		}
1062		if err := tmp.Close(); err != nil {
1063			os.Remove(tmpName)
1064			return fmt.Errorf("cannot save registry %q: %w", path, err)
1065		}
1066		if err := renameTempFile(tmpName, path); err != nil {
1067			os.Remove(tmpName)
1068			return fmt.Errorf("cannot save registry %q: %w", path, err)
1069		}
1070		return nil
1071	}
1072

