267	func runBatchImport(args []string, stdout io.Writer) error {
268		fs := flag.NewFlagSet("batch-import", flag.ContinueOnError)
269		fs.SetOutput(io.Discard)
270		registryPath := fs.String("registry", "", "registry `file` to read and write")
271		inputPath := fs.String("input", "", "read-only JSON manifest `file` to import")
272		if err := fs.Parse(args); err != nil {
273			if errors.Is(err, flag.ErrHelp) {
274				fmt.Fprint(stdout, rootUsage())
275				return nil
276			}
277			return &usageError{msg: "batch-import: " + err.Error(), usage: batchImportUsage}
278		}
279		if fs.NArg() != 0 {
280			return &usageError{
281				msg:   fmt.Sprintf("batch-import: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
282				usage: batchImportUsage,
283			}
284		}
285		if *registryPath == "" || *inputPath == "" {
286			var missing []string
287			if *registryPath == "" {
288				missing = append(missing, "--registry")
289			}
290			if *inputPath == "" {
291				missing = append(missing, "--input")
292			}
293			return &usageError{
294				msg:   "batch-import: missing required flag(s): " + strings.Join(missing, ", "),
295				usage: batchImportUsage,
296			}
297		}
298	
299		// The manifest is read-only and is parsed (and fully validated) before
300		// the registry is loaded or written, so bad input cannot touch it.
301		data, err := os.ReadFile(*inputPath)
302		if err != nil {
303			return fmt.Errorf("batch-import: cannot read input file %q: %w", *inputPath, err)
304		}
305		inputs, err := batchreg.ParseManifest(data)
306		if err != nil {
307			return fmt.Errorf("batch-import: invalid input file %q: %w", *inputPath, err)
308		}
309	
310		reg, existed, err := batchreg.Load(*registryPath)
311		if err != nil {
312			return fmt.Errorf("batch-import: %w", err)
313		}
314		outcomes, err := batchreg.Import(reg, inputs)
315		if err != nil {
316			return fmt.Errorf("batch-import: %w", err)
317		}
318	
319		type importResultJSON struct {
320			Batch    string `json:"batch"`
321			Product  string `json:"product"`
322			Quantity int64  `json:"quantity"`
323			Unit     string `json:"unit"`
324			Status   string `json:"status"`
325		}
326		results := make([]importResultJSON, len(outcomes))
327		anyCreated := false
328		for i, o := range outcomes {
329			status := "duplicate"
330			if o.Created {
331				status = "created"
332				anyCreated = true
333			}
334			results[i] = importResultJSON{
335				Batch:    o.Batch.Batch,
336				Product:  o.Batch.Product,
337				Quantity: o.Batch.Quantity,
338				Unit:     o.Batch.Unit,
339				Status:   status,
340			}
341		}
342	
343		// An all-duplicate manifest must leave bytes and mtime untouched, so the
344		// registry is written only when at least one record was newly created.
345		if anyCreated {
346			if err := batchreg.Save(*registryPath, reg); err != nil {
