519			},
520		}
521		manifestContent := []byte(`[{"batch":"NEW","product":"P","quantity":1,"unit":"kg"}]`)
522		for name, tc := range registries {
523			t.Run(name, func(t *testing.T) {
524				dir := t.TempDir()
525				registry := filepath.Join(dir, "reg.json")
526				manifest := filepath.Join(dir, "in.json")
527				if err := os.WriteFile(registry, tc.content, 0o644); err != nil {
528					t.Fatal(err)
529				}
530				if err := os.WriteFile(manifest, manifestContent, 0o644); err != nil {
531					t.Fatal(err)
532				}
533				pinned := time.Date(2003, time.April, 5, 6, 7, 8, 0, time.UTC)
534				if err := os.Chtimes(registry, pinned, pinned); err != nil {
535					t.Fatal(err)
536				}
537	
538				assertBlocked := func(err error, stdout *bytes.Buffer) {
539					t.Helper()
540					if err == nil {
541						t.Fatal("malformed registry must be rejected")
542					}
543					msg := err.Error()
544					for _, want := range []string{registry, tc.pos, tc.field} {
545						if !strings.Contains(msg, want) {
546							t.Fatalf("error must mention %q: %v", want, msg)
547						}
548					}
549					if tc.batch != "" && !strings.Contains(msg, tc.batch) {
550						t.Fatalf("error must cite batch %q: %v", tc.batch, msg)
551					}
552					if tc.batch == "" && strings.Contains(msg, "�") {
553						t.Fatalf("error must not cite a substituted id: %v", msg)
554					}
555					if stdout.Len() != 0 {
556						t.Fatalf("stdout must stay empty: %q", stdout.String())
557					}
558				}
559	
560				var stdout bytes.Buffer
561				err := runBatchRegister([]string{
562					"--registry", registry, "--batch", "NEW", "--product", "P",
563					"--quantity", "1", "--unit", "kg",
564				}, &stdout)
565				assertBlocked(err, &stdout)
566	
567				stdout.Reset()
568				err = runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout)
569				assertBlocked(err, &stdout)
570	
571				after, rerr := os.ReadFile(registry)
572				if rerr != nil || !bytes.Equal(after, tc.content) {
573					t.Fatalf("registry bytes changed: %q", after)
574				}
575				info, serr := os.Stat(registry)
576				if serr != nil || !info.ModTime().Equal(pinned) {
577					t.Fatalf("registry mtime changed: %v", serr)
578				}
579				mAfter, merr := os.ReadFile(manifest)
580				if merr != nil || !bytes.Equal(mAfter, manifestContent) {
581					t.Fatal("manifest was modified")
582				}
583			})
584		}
585	}
586	
587	// Valid Unicode — CJK, emoji and a genuine U+FFFD — works end to end, and a
588	// JSON escape means the same text as the directly written character.
589	func TestUnicodeRoundTripsThroughBothCommands(t *testing.T) {
590		dir := t.TempDir()
591		registry := filepath.Join(dir, "reg.json")
592	
593		var stdout bytes.Buffer
594		if err := runBatchRegister([]string{
595			"--registry", registry, "--batch", " 批次-1 ", "--product", "产品😀",
596			"--quantity", "7", "--unit", "千克",
597		}, &stdout); err != nil {
598			t.Fatal(err)
599		}
600		if !strings.Contains(stdout.String(), `"status":"created"`) ||
601			!strings.Contains(stdout.String(), `"batch":"批次-1"`) {
602			t.Fatalf("unexpected output: %q", stdout.String())
603		}
604	
605		// The same batch via a JSON \uXXXX escape pair for the emoji must be a
606		// duplicate, while a direct genuine U+FFFD registers a distinct batch.
607		manifest := filepath.Join(dir, "in.json")
608		writeFile(t, manifest, `[
609			{"batch":"批次-1","product":"产品😀","quantity":7,"unit":"千克"},
610			{"batch":"B-FFFD","product":"P�","quantity":1,"unit":"kg"}
611		]`)
612		stdout.Reset()
613		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
614			t.Fatal(err)
615		}
616		var out importOutput
617		if err := json.Unmarshal(bytes.TrimSpace(stdout.Bytes()), &out); err != nil {
618			t.Fatal(err)
619		}
620		if len(out.Results) != 2 ||
621			out.Results[0].Status != "duplicate" || out.Results[0].Product != "产品😀" ||
622			out.Results[1].Status != "created" || out.Results[1].Product != "P�" {
623			t.Fatalf("unexpected results: %s", stdout.String())
624		}
625	
626		// Re-registering the genuine U+FFFD batch directly is a duplicate, and a
627		// malformed byte in a different flag is still refused.
628		stdout.Reset()
629		if err := runBatchRegister([]string{
630			"--registry", registry, "--batch", "B-FFFD", "--product", "P�",
631			"--quantity", "1", "--unit", "kg",
632		}, &stdout); err != nil {
633			t.Fatalf("genuine U+FFFD must stay usable: %v", err)
634		}
635		if !strings.Contains(stdout.String(), `"status":"duplicate"`) {
636			t.Fatalf("expected duplicate: %q", stdout.String())
637		}
638	}
639	
640	// registerCLI runs one batch-register invocation and returns its stdout.
641	func registerCLI(t *testing.T, registry, batch, product, quantity, unit string) (string, error) {
642		t.Helper()
643		var stdout bytes.Buffer
644		err := runBatchRegister([]string{
645			"--registry", registry,
646			"--batch", batch,
647			"--product", product,
648			"--quantity", quantity,
649			"--unit", unit,
650		}, &stdout)
651		return stdout.String(), err
652	}
653	
654	type registerResult struct {
655		Batch    string `json:"batch"`
656		Product  string `json:"product"`
657		Quantity int64  `json:"quantity"`
658		Unit     string `json:"unit"`
659		Status   string `json:"status"`
660	}
661	
662	// decodeRegisterResult parses stdout as exactly one JSON object carrying
663	// exactly the four record fields plus status — nothing before, after or
664	// beyond it, and no extra or missing members.
665	func decodeRegisterResult(t *testing.T, stdout string) registerResult {
666		t.Helper()
667		dec := json.NewDecoder(strings.NewReader(stdout))
668		var keys map[string]json.RawMessage
669		if err := dec.Decode(&keys); err != nil {
670			t.Fatalf("stdout is not a JSON object: %v (%q)", err, stdout)
671		}
672		if err := dec.Decode(&struct{}{}); err != io.EOF {
673			t.Fatalf("stdout must hold exactly one JSON object, got %q", stdout)
674		}
675		for _, want := range []string{"batch", "product", "quantity", "unit", "status"} {
676			if _, ok := keys[want]; !ok {
677				t.Fatalf("result object is missing field %q: %q", want, stdout)
678			}
679			delete(keys, want)
680		}
681		if len(keys) != 0 {
682			t.Fatalf("result object carries unexpected field(s): %q", stdout)
683		}
684		var res registerResult
685		if err := json.Unmarshal([]byte(stdout), &res); err != nil {
686			t.Fatalf("result object does not match the record shape: %v (%q)", err, stdout)
687		}
688		return res
689	}
690	
691	// readStoredBatches decodes the registry file into its records, in file order.
692	func readStoredBatches(t *testing.T, path string) []registerResult {
693		t.Helper()
694		data, err := os.ReadFile(path)
695		if err != nil {
696			t.Fatal(err)
697		}
698		var stored struct {
699			Version int              `json:"version"`
700			Batches []registerResult `json:"batches"`
701		}
702		if err := json.Unmarshal(data, &stored); err != nil {
703			t.Fatalf("registry file does not decode: %v (%s)", err, data)
704		}
705		if stored.Version != 1 {
706			t.Fatalf("registry version = %d, want 1", stored.Version)
707		}
708		return stored.Batches
709	}
710	
711	// pinRegistry reads the registry and pins a distinctive past mtime so any
712	// rewrite — even one reproducing identical bytes — is observable.
713	func pinRegistry(t *testing.T, path string) (content []byte, pinned time.Time) {
714		t.Helper()
715		pinned = time.Date(2004, time.May, 6, 7, 8, 9, 0, time.UTC)
716		if err := os.Chtimes(path, pinned, pinned); err != nil {
717			t.Fatal(err)
718		}
719		content, err := os.ReadFile(path)
720		if err != nil {
721			t.Fatal(err)
722		}
723		return content, pinned
724	}
725	
726	// assertRegistryUntouched fails if the file's bytes or mtime differ from the
727	// pinned snapshot.
728	func assertRegistryUntouched(t *testing.T, path string, content []byte, pinned time.Time) {
729		t.Helper()
730		after, err := os.ReadFile(path)
731		if err != nil {
732			t.Fatal(err)
733		}
734		if !bytes.Equal(after, content) {
735			t.Fatalf("registry bytes changed:\nbefore: %s\nafter:  %s", content, after)
736		}
737		info, err := os.Stat(path)
738		if err != nil {
739			t.Fatal(err)
740		}
741		if !info.ModTime().Equal(pinned) {
742			t.Fatalf("registry mtime changed: got %v, want %v", info.ModTime(), pinned)
743		}
744	}
745	
746	// A first registration returns "created"; re-submitting the same record —
747	// spelled with padding and leading zeros that normalize away — confirms the
748	// stored record as "duplicate", echoing the registered four fields as the
749	// only JSON object on stdout. The file keeps exactly its earlier records,
750	// the other batch's fields and position included, and neither its bytes nor
751	// its mtime move during the confirmation.
752	func TestBatchRegisterCLIDuplicateConfirm(t *testing.T) {
753		dir := t.TempDir()
754		registry := filepath.Join(dir, "reg.json")
755	
756		stdout, err := registerCLI(t, registry, "B-000", "P-0", "5", "box")
757		if err != nil {
758			t.Fatal(err)
759		}
760		if res := decodeRegisterResult(t, stdout); res.Status != "created" {
761			t.Fatalf("first registration of B-000 = %+v, want created", res)
762		}
763	
764		stdout, err = registerCLI(t, registry, " B-001 ", " P-7 ", "000120", " kg ")
765		if err != nil {
766			t.Fatal(err)
767		}
768		created := decodeRegisterResult(t, stdout)
769		want := registerResult{Batch: "B-001", Product: "P-7", Quantity: 120, Unit: "kg", Status: "created"}
770		if created != want {
771			t.Fatalf("first registration = %+v, want %+v", created, want)
772		}
773	
774		content, pinned := pinRegistry(t, registry)
775	
776		// The same record with the padding and leading zeros already removed is
777		// the identical effective value: a duplicate, not a new record.
778		stdout, err = registerCLI(t, registry, "B-001", "P-7", "120", "kg")
779		if err != nil {
780			t.Fatalf("identical re-registration must succeed: %v", err)
781		}
782		dup := decodeRegisterResult(t, stdout)
783		want.Status = "duplicate"
784		if dup != want {
785			t.Fatalf("duplicate confirmation = %+v, want %+v", dup, want)
786		}
787		assertRegistryUntouched(t, registry, content, pinned)
788	
789		// Still exactly one record per batch, the other batch first and unchanged.
790		batches := readStoredBatches(t, registry)
791		if len(batches) != 2 {
792			t.Fatalf("registry holds %d records, want 2: %v", len(batches), batches)
793		}
794		if batches[0] != (registerResult{Batch: "B-000", Product: "P-0", Quantity: 5, Unit: "box"}) {
795			t.Fatalf("other batch's record changed: %+v", batches[0])
796		}
797		if batches[1] != (registerResult{Batch: "B-001", Product: "P-7", Quantity: 120, Unit: "kg"}) {
798			t.Fatalf("stored record changed: %+v", batches[1])
799		}
800	}
801	
802	// A registry file whose layout differs from what Save would write — compact,
803	// members in another order — is still not re-saved to confirm a duplicate:
804	// bytes and mtime stay exactly as they were.
805	func TestBatchRegisterCLIDuplicateKeepsForeignFileLayout(t *testing.T) {
806		dir := t.TempDir()
807		registry := filepath.Join(dir, "reg.json")
808		original := `{"batches":[{"unit":"kg","quantity":120,"product":"P-7","batch":"B-001"}],"version":1}`
809		writeFile(t, registry, original)
810		content, pinned := pinRegistry(t, registry)
811	
812		stdout, err := registerCLI(t, registry, "B-001", "P-7", "120", "kg")
813		if err != nil {
814			t.Fatalf("duplicate confirmation must succeed: %v", err)
815		}
816		if res := decodeRegisterResult(t, stdout); res.Status != "duplicate" {
817			t.Fatalf("got %+v, want duplicate", res)
818		}
819		assertRegistryUntouched(t, registry, content, pinned)
820		if after, _ := os.ReadFile(registry); string(after) != original {
821			t.Fatalf("foreign layout was rewritten:\nbefore: %s\nafter:  %s", original, after)
822		}
823	}
824	
825	// Re-registering a batch id with any differing field fails: stdout stays
826	// empty, the error names the batch and every mismatching field — never just
827	// one of several — and the file keeps its bytes and mtime. Interior
828	// whitespace and casing are significant, so "p-7" and "k g" are conflicts,
829	// not duplicates.
830	func TestBatchRegisterCLIConflictReportsAllDifferingFields(t *testing.T) {
831		cases := map[string]struct {
832			product  string
833			quantity string
834			unit     string
835			fields   []string
836		}{
837			"product casing differs":      {"p-7", "120", "kg", []string{"product"}},
838			"unit interior space differs": {"P-7", "120", "k g", []string{"unit"}},
839			"quantity differs":            {"P-7", "121", "kg", []string{"quantity"}},
840			"all three differ":            {"P-8", "121", "g", []string{"product", "quantity", "unit"}},
841		}
842		for name, tc := range cases {
843			t.Run(name, func(t *testing.T) {
844				dir := t.TempDir()
845				registry := filepath.Join(dir, "reg.json")
846				writeFile(t, registry, `{"version":1,"batches":[`+
847					`{"batch":"B-000","product":"P-0","quantity":5,"unit":"box"},`+
848					`{"batch":"B-001","product":"P-7","quantity":120,"unit":"kg"}]}`)
849				content, pinned := pinRegistry(t, registry)
850	
851				stdout, err := registerCLI(t, registry, "B-001", tc.product, tc.quantity, tc.unit)
852				if err == nil {
853					t.Fatal("a conflicting re-registration must fail")
854				}
855				if stdout != "" {
856					t.Fatalf("stdout must stay empty on conflict, got %q", stdout)
857				}
858				msg := err.Error()
859				if !strings.Contains(msg, strconv.Quote("B-001")) {
860					t.Fatalf("error must name the batch: %v", msg)
861				}
862				for _, field := range tc.fields {
863					if !strings.Contains(msg, field) {
864						t.Fatalf("error must report differing field %q: %v", field, msg)
865					}
866				}
867				assertRegistryUntouched(t, registry, content, pinned)
868	
869				batches := readStoredBatches(t, registry)
870				if len(batches) != 2 || batches[1].Product != "P-7" ||
871					batches[1].Quantity != 120 || batches[1].Unit != "kg" {
872					t.Fatalf("the conflict must not overwrite the stored record: %v", batches)
873				}
874			})
875		}
876	}
877	
878	// Batch ids compare byte for byte: "b-001" is a different id from "B-001" and
879	// registers as its own record, after which it confirms duplicates of its own.
880	func TestBatchRegisterCLIBatchIDCaseSensitive(t *testing.T) {
881		dir := t.TempDir()
882		registry := filepath.Join(dir, "reg.json")
883	
884		if _, err := registerCLI(t, registry, "B-001", "P-7", "120", "kg"); err != nil {
885			t.Fatal(err)
886		}
887		stdout, err := registerCLI(t, registry, "b-001", "P-7", "120", "kg")
888		if err != nil {
889			t.Fatalf("a case-distinct batch id must register: %v", err)
890		}
891		if res := decodeRegisterResult(t, stdout); res.Status != "created" || res.Batch != "b-001" {
892			t.Fatalf("got %+v, want created b-001", res)
893		}
894	
895		batches := readStoredBatches(t, registry)
896		if len(batches) != 2 || batches[0].Batch != "B-001" || batches[1].Batch != "b-001" {
897			t.Fatalf("want B-001 and b-001 as separate records in order, got %v", batches)
898		}
899	
900		stdout, err = registerCLI(t, registry, "b-001", "P-7", "120", "kg")
901		if err != nil {
902			t.Fatal(err)
903		}
904		if res := decodeRegisterResult(t, stdout); res.Status != "duplicate" {
905			t.Fatalf("got %+v, want duplicate", res)
906		}
907		if batches := readStoredBatches(t, registry); len(batches) != 2 {
908			t.Fatalf("duplicate confirmation added a record: %v", batches)
909		}
910	}
911	
912	// Quantities compare as integers right up to the int64 ceiling: MaxQuantity
913	// registers and confirms as a duplicate, one less conflicts on quantity, and
914	// anything above the ceiling is rejected as an illegal --quantity value —
915	// never a created or duplicate result.
916	func TestBatchRegisterCLIQuantityBoundaries(t *testing.T) {
917		dir := t.TempDir()
918		registry := filepath.Join(dir, "reg.json")
919		const max = "9223372036854775807"
920	
921		stdout, err := registerCLI(t, registry, "B-MAX", "P-7", max, "kg")
922		if err != nil {
923			t.Fatalf("the maximum quantity must register: %v", err)
924		}
925		if res := decodeRegisterResult(t, stdout); res.Status != "created" || res.Quantity != 9223372036854775807 {
926			t.Fatalf("got %+v, want created with quantity 9223372036854775807", res)
927		}
928	
929		stdout, err = registerCLI(t, registry, "B-MAX", "P-7", max, "kg")
930		if err != nil {
931			t.Fatalf("the maximum quantity must confirm as duplicate: %v", err)
932		}
933		if res := decodeRegisterResult(t, stdout); res.Status != "duplicate" || res.Quantity != 9223372036854775807 {
934			t.Fatalf("got %+v, want duplicate with quantity 9223372036854775807", res)
935		}
936	
937		content, pinned := pinRegistry(t, registry)
938	
939		stdout, err = registerCLI(t, registry, "B-MAX", "P-7", "9223372036854775806", "kg")
940		if err == nil {
941			t.Fatal("one less than the stored quantity must conflict, not confirm")
942		}
943		if stdout != "" {
944			t.Fatalf("stdout must stay empty on conflict, got %q", stdout)
945		}
946		if msg := err.Error(); !strings.Contains(msg, strconv.Quote("B-MAX")) || !strings.Contains(msg, "quantity") {
947			t.Fatalf("error must name the batch and the quantity field: %v", msg)
948		}
949		assertRegistryUntouched(t, registry, content, pinned)
950	
951		stdout, err = registerCLI(t, registry, "B-OVER", "P-7", "9223372036854775808", "kg")
952		if err == nil {
953			t.Fatal("a quantity above the maximum must be rejected")
954		}
955		if stdout != "" {
956			t.Fatalf("stdout must stay empty on invalid input, got %q", stdout)
957		}
958		if msg := err.Error(); !strings.Contains(msg, "--quantity") || !strings.Contains(msg, max) {
959			t.Fatalf("error must reject --quantity against the maximum %s: %v", max, msg)
960		}
961		assertRegistryUntouched(t, registry, content, pinned)
962	
963		if batches := readStoredBatches(t, registry); len(batches) != 1 || batches[0].Quantity != 9223372036854775807 {
964			t.Fatalf("failures must not add or alter records: %v", batches)
965		}
966	}
